#!/usr/bin/env bash
# Set (or clear) the picture the lock screen shows.
#
# The lock screen is hyprlock, and its background comes from the variable
# `$background_image` in ~/.config/hypr/hyprlock/colors.conf. That file is
# generated by matugen from the desktop wallpaper, so writing to it directly
# would be undone the next time the wallpaper changes -- and would also mean
# you could never have a lock picture different from your desktop one.
#
# So the lock choice lives in its own file, sourced from hyprlock.conf *after*
# colors.conf. A later assignment wins, which is what makes this an override
# instead of a copy. Deleting the assignment (--clear) puts the lock screen
# back to following the desktop wallpaper, which is the default behaviour.
#
#   set-lock-wallpaper.sh /path/to/picture.jpg   ... use this picture
#   set-lock-wallpaper.sh --clear                ... follow the desktop again
#   set-lock-wallpaper.sh                        ... print the current setting
set -euo pipefail

CONFIG_DIR="${XDG_CONFIG_HOME:-$HOME/.config}"
LOCK_DIR="$CONFIG_DIR/hypr/hyprlock"
OVERRIDE_FILE="$LOCK_DIR/lock-wallpaper.conf"

usage() {
    echo "usage: $(basename "$0") <image path> | --clear" >&2
    exit 2
}

current_image() {
    # The override wins if it sets anything at all.
    if [[ -f "$OVERRIDE_FILE" ]]; then
        local from_override
        from_override="$(sed -n 's/^[[:space:]]*\$background_image[[:space:]]*=[[:space:]]*//p' "$OVERRIDE_FILE" | tail -n 1)"
        if [[ -n "$from_override" ]]; then
            printf '%s\n' "$from_override"
            return 0
        fi
    fi
    # Otherwise it is whatever matugen generated for the desktop wallpaper.
    sed -n 's/^[[:space:]]*\$background_image[[:space:]]*=[[:space:]]*//p' "$LOCK_DIR/colors.conf" 2>/dev/null | tail -n 1
}

write_override() {
    local image="${1:-}"
    mkdir -p "$LOCK_DIR"
    {
        echo "# Set by the wallpaper picker: the lock screen's own picture."
        echo "# Sourced after colors.conf (which matugen regenerates), so this wins."
        echo "# Remove this file, or run set-lock-wallpaper.sh --clear, to go back"
        echo "# to showing the desktop wallpaper on the lock screen."
        if [[ -n "$image" ]]; then
            printf '$background_image = %s\n' "$image"
        fi
    } > "$OVERRIDE_FILE.tmp"
    mv "$OVERRIDE_FILE.tmp" "$OVERRIDE_FILE"
}

case "${1:-}" in
    "")
        current_image
        ;;
    --clear|clear|--unset)
        write_override ""
        echo "Lock screen follows the desktop wallpaper again."
        ;;
    -h|--help)
        usage
        ;;
    *)
        image="$1"
        if [[ ! -f "$image" ]]; then
            echo "No such file: $image" >&2
            exit 1
        fi
        # Absolute path, because hyprlock does not resolve relative ones.
        image="$(readlink -f -- "$image")"
        write_override "$image"
        echo "Lock screen picture: $image"
        ;;
esac
